fnull(Category_Code,\'\')) desc) rw from zouk-wh.maplemonk.final_sku_master) where rw = 1 )p1 on lower(replace(fi.sku,\' \',\'\')) = lower(replace(p1.skucode,\' \',\'\')) LEFT JOIN (select * from (Select * , row_number() over (partition by lower(marketplace) order by 1) rw from maplemonk.marketplace_mapping ) where rw =1 ) mm ON lower(fi.marketplace) = lower(mm.marketplace) left join ( select PARSE_DATE(\'%d-%b-%y\',START_DATE) START_DATE ,PARSE_DATE(\'%d-%b-%y\',END_DATE) END_DATE ,category_code ,cast(replace(cogs,\',\',\'\') as float64) as cogs from MapleMonk.zouk_db_sku_mrp_cogs qualify row_number() over(partition by START_DATE,END_DATE,lower(category_code) order by 1) = 1 )cogs on cast(return_date as date) >= cast(cogs.START_DATE as date) and cast(return_date as date) <= cast(cogs.END_DATE as date) and lower(coalesce(p.category_code,p1.category_code) ) = lower(cogs.category_code) left join (Select * from ( select *,row_number() over(partition by commonsku order by 1)rw from maplemonk.final_sku_master )where rw = 1 ) fsm on lower(fsm.commonsku) = lower(coalesce(p.commonsku,p1.commonsku) ) and cast(return_date as date) >= \'2025-09-22\' left join (Select * from ( select *,row_number() over(partition by commonsku order by 1)rw from `MapleMonk.FINAL_SKU_MASTER_TEMP` )where rw = 1 ) ofsm on lower(ofsm.commonsku) = lower(coalesce(p.commonsku,p1.commonsku) ) and cast(return_date as date) < \'2025-09-22\' left join ( select PARSE_DATE(\'%d-%b-%y\',START_DATE) START_DATE ,PARSE_DATE(\'%d-%b-%y\',END_DATE) END_DATE ,MARKETPLACE ,cast(replace(ifnull(commission_value,\'0\'),\'%\',\'\') as float64)/100 as commission_value ,cast(Actual_Value as float64) as Actual_Value from MapleMonk.zouk_db_Marketplace_Commissions where upper(PANDL_CATEGORY) = \'TRADE MARGIN\' ) tm on cast(return_date as date) >= cast(tm.START_DATE as date) and cast(return_date as date) <= cast(tm.END_DATE as date) and lower(fi.marketplace) = lower(tm.MARKETPLACE) left join ( select PARSE_DATE(\'%d-%b-%y\',START_DATE) START_DATE ,PARSE_DATE(\'%d-%b-%y\',END_DATE) END_DATE ,MARKETPLACE ,case when lower(Commission_Type) like \'%percent%\' then cast(replace(commission_value,\'%\',\'\') as float64)/100 end as commission_value ,case when lower(Commission_Type) not like \'%percent%\' then cast(replace(commission_value,\'%\',\'\') as float64) end as actual_value from MapleMonk.c_cogs where upper(PANDL_CATEGORY) = \'C COGS\' )ccogs on cast(return_date as date) >= cast(ccogs.START_DATE as date) and cast(return_date as date) <= cast(ccogs.END_DATE as date) and lower(fi.marketplace) = lower(ccogs.MARKETPLACE) left join ( select PARSE_DATE(\'%d-%b-%y\',START_DATE) START_DATE ,PARSE_DATE(\'%d-%b-%y\',END_DATE) END_DATE ,MARKETPLACE ,cast(replace(Estimated_Logistics_Cost,\'%\',\'\') as float64)/100 as commission_value ,cast(Actual_Value as float64) as Actual_Value from MapleMonk.zouk_db_LOGISTICS_COSTS qualify row_number() over(partition by START_DATE,END_DATE,lower(MARKETPLACE) order by 1) = 1 )lc on cast(return_date as date) >= cast(lc.START_DATE as date) and cast(return_date as date) <= cast(lc.END_DATE as date) and lower(fi.marketplace) = lower(lc.MARKETPLACE) left join ( select distinct upper(MARKETPLACE) MARKETPLACE from MapleMonk.zouk_db_Marketplace_Commissions where upper(PANDL_CATEGORY) = \'TRADE MARGIN\' ) tm1 on lower(fi.marketplace) = lower(tm1.MARKETPLACE) ); CREATE OR REPLACE TABLE MapleMonk.Zouk_Rhea_Kapoor_PandL AS WITH Eligible_PandL AS ( SELECT * FROM `MapleMonk.zouk_secondary_pandl` WHERE LOWER(collection) LIKE \'%rhea%\' ), April_Row_Count AS ( SELECT COUNT(*) AS total_entries_in_april FROM Eligible_PandL WHERE DATE BETWEEN \'2025-04-01\' AND \'2025-04-30\' ) SELECT e.*, CASE WHEN e.DATE BETWEEN \'2025-04-01\' AND \'2025-04-30\' THEN 4484904.0 / a.total_entries_in_april ELSE 0.0 END AS Production_Cost, CASE WHEN e.DATE BETWEEN \'2025-04-01\' AND \'2025-04-30\' THEN 2000000.0 / a.total_entries_in_april ELSE 0.0 END AS Contract_Cost FROM Eligible_PandL e CROSS JOIN